#!/usr/bin/env node
'use strict';

/**
 * Validates an approved production release manifest.
 *
 * The manifest is the signed record that ties a release to an exact source
 * revision, an exact set of image digests, a bundle checksum, and a named
 * approval. It is generated by the deployment workflow and verified before a
 * rollout.
 *
 * Usage:
 *   node scripts/validate-release-manifest.js --manifest <path> [--json]
 *   node scripts/validate-release-manifest.js --manifest <path> --require-bundle-archive
 *
 * Environment (all optional; the defaults match deploy/docker-compose.prod.yml):
 *   BACKEND_IMAGE, FRONTEND_IMAGE, MONGO_IMAGE, CADDY_IMAGE
 *   EXPECTED_BACKEND_REPOSITORY, EXPECTED_FRONTEND_REPOSITORY,
 *   EXPECTED_MONGO_REPOSITORY, EXPECTED_CADDY_REPOSITORY
 *   RELEASE_MANIFEST_SIGNATURE   detached signature of the manifest
 *   RELEASE_MANIFEST_PUBLIC_KEY  public key used to verify the signature
 *   REQUIRE_RELEASE_MANIFEST_SIGNATURE  fail closed when the manifest is unsigned
 *   BUNDLE_ARCHIVE               release bundle whose checksum must match
 *   RELEASE_REQUIRED_APPROVAL_ROLE  approval role that must be present
 *
 * `--require-bundle-archive` makes BUNDLE_ARCHIVE mandatory: the recorded
 * bundle checksum is then verified against the actual archive bytes instead
 * of only being checked for the correct format. The production preflight
 * always uses it.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

const REPO_ROOT = path.resolve(__dirname, '..');
const GHCR_REPOSITORY = process.env.EXPECTED_GHCR_REPOSITORY || process.env.GITHUB_REPOSITORY || 'REPLACE_OWNER/REPLACE_REPOSITORY';
const DEFAULT_BACKEND_REPOSITORY = `ghcr.io/${GHCR_REPOSITORY}/backend`;
const DEFAULT_FRONTEND_REPOSITORY = `ghcr.io/${GHCR_REPOSITORY}/frontend`;
const DEFAULT_MONGO_REPOSITORY = 'docker.io/library/mongo';
const DEFAULT_CADDY_REPOSITORY = 'docker.io/library/caddy';

const SHA_PATTERN = /^[0-9a-f]{64}$/;
const SOURCE_SHA_PATTERN = /^[0-9a-f]{40}$/;
const DIGEST_REFERENCE_PATTERN = /^([^\s@]+)@sha256:([0-9a-f]{64})$/;

function parseArguments(argv) {
  const options = { manifest: '', json: false, requireBundleArchive: false };
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === '--manifest') {
      index += 1;
      options.manifest = path.resolve(argv[index] || '');
    } else if (argument === '--json') {
      options.json = true;
    } else if (argument === '--require-bundle-archive') {
      options.requireBundleArchive = true;
    } else if (argument === '--help' || argument === '-h') {
      options.help = true;
    } else {
      throw new Error(`Unknown argument: ${argument}`);
    }
  }
  return options;
}

function isIsoTimestamp(value) {
  if (typeof value !== 'string' || value.trim().length === 0) {
    return false;
  }
  const parsed = Date.parse(value);
  return Number.isFinite(parsed);
}

function sha256File(filePath) {
  return crypto.createHash('sha256').update(fs.readFileSync(filePath)).digest('hex');
}

function countExceptions(relativePath) {
  const filePath = path.join(REPO_ROOT, relativePath);
  if (!fs.existsSync(filePath)) {
    return null;
  }
  const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  return Array.isArray(parsed.exceptions) ? parsed.exceptions.length : null;
}

function verifySignature(manifestPath, signaturePath, publicKeyPath) {
  const attempts = [
    ['pkeyutl-ed25519', [
      'pkeyutl',
      '-verify',
      '-pubin',
      '-inkey',
      publicKeyPath,
      '-rawin',
      '-in',
      manifestPath,
      '-sigfile',
      signaturePath,
    ]],
    ['dgst-sha256', [
      'dgst',
      '-sha256',
      '-verify',
      publicKeyPath,
      '-signature',
      signaturePath,
      manifestPath,
    ]],
  ];

  const failures = [];
  for (const [name, args] of attempts) {
    try {
      execFileSync('openssl', args, { stdio: ['ignore', 'pipe', 'pipe'] });
      return { verified: true, method: name, failures };
    } catch (error) {
      failures.push(`${name}: ${(error.stderr || error.message).toString().trim()}`);
    }
  }

  return { verified: false, method: '', failures };
}

function main() {
  const options = parseArguments(process.argv.slice(2));
  if (options.help) {
    process.stdout.write(
      'Usage: node scripts/validate-release-manifest.js --manifest <path> [--json] [--require-bundle-archive]\n'
    );
    return 0;
  }

  const problems = [];
  const report = { ok: true, manifest: options.manifest, problems: [], signature: { verified: false } };

  if (!options.manifest) {
    process.stderr.write('Release manifest error: --manifest <path> is required.\n');
    return 1;
  }
  if (!fs.existsSync(options.manifest)) {
    process.stderr.write(`Release manifest error: ${options.manifest} does not exist.\n`);
    return 1;
  }

  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(options.manifest, 'utf8'));
  } catch (error) {
    process.stderr.write(`Release manifest error: the manifest is not valid JSON (${error.message}).\n`);
    return 1;
  }

  if (manifest.manifestVersion !== 1) {
    problems.push('manifestVersion must be 1.');
  }
  if (typeof manifest.releaseId !== 'string' || manifest.releaseId.trim().length < 3) {
    problems.push('releaseId must identify the release.');
  }
  if (typeof manifest.sourceSha !== 'string' || !SOURCE_SHA_PATTERN.test(manifest.sourceSha)) {
    problems.push('sourceSha must be an exact 40 character lowercase commit SHA.');
  }
  if (!isIsoTimestamp(manifest.generatedAt)) {
    problems.push('generatedAt must be an ISO-8601 timestamp.');
  }
  if (!isIsoTimestamp(manifest.expiresAt)) {
    problems.push('expiresAt must be an ISO-8601 timestamp.');
  } else if (Date.parse(manifest.expiresAt) <= Date.now()) {
    problems.push(`expiresAt (${manifest.expiresAt}) is in the past; the release approval is no longer valid.`);
  }

  const expectedImages = {
    backend: {
      expected: process.env.BACKEND_IMAGE || '',
      repository: process.env.EXPECTED_BACKEND_REPOSITORY || DEFAULT_BACKEND_REPOSITORY,
    },
    frontend: {
      expected: process.env.FRONTEND_IMAGE || '',
      repository: process.env.EXPECTED_FRONTEND_REPOSITORY || DEFAULT_FRONTEND_REPOSITORY,
    },
    mongo: {
      expected: process.env.MONGO_IMAGE || '',
      repository: process.env.EXPECTED_MONGO_REPOSITORY || DEFAULT_MONGO_REPOSITORY,
    },
    caddy: {
      expected: process.env.CADDY_IMAGE || '',
      repository: process.env.EXPECTED_CADDY_REPOSITORY || DEFAULT_CADDY_REPOSITORY,
    },
  };

  if (!manifest.images || typeof manifest.images !== 'object') {
    problems.push('images must list the backend, frontend, mongo, and caddy references.');
  } else {
    for (const [name, expectation] of Object.entries(expectedImages)) {
      const value = manifest.images[name];
      if (typeof value !== 'string') {
        problems.push(`images.${name} is required.`);
        continue;
      }
      const match = DIGEST_REFERENCE_PATTERN.exec(value);
      if (!match) {
        problems.push(`images.${name} must be an exact <repository>@sha256:<64 hex> reference; got '${value}'.`);
        continue;
      }
      if (match[1] !== expectation.repository) {
        problems.push(
          `images.${name} repository '${match[1]}' does not match the expected repository '${expectation.repository}'.`
        );
      }
      if (expectation.expected && value !== expectation.expected) {
        problems.push(`images.${name} does not match the image that is scheduled for deployment.`);
      }
    }
  }

  if (!manifest.bundle || typeof manifest.bundle !== 'object') {
    problems.push('bundle must record the release bundle name and checksum.');
  } else {
    if (typeof manifest.bundle.name !== 'string' || manifest.bundle.name.trim().length === 0) {
      problems.push('bundle.name is required.');
    }
    if (typeof manifest.bundle.sha256 !== 'string' || !SHA_PATTERN.test(manifest.bundle.sha256)) {
      problems.push('bundle.sha256 must be a 64 character lowercase sha256 digest.');
    } else if (options.requireBundleArchive && !process.env.BUNDLE_ARCHIVE) {
      problems.push(
        'BUNDLE_ARCHIVE is required: the recorded bundle checksum must be verified against the actual release bundle archive.'
      );
    } else if (process.env.BUNDLE_ARCHIVE) {
      if (!fs.existsSync(process.env.BUNDLE_ARCHIVE)) {
        problems.push(`BUNDLE_ARCHIVE '${process.env.BUNDLE_ARCHIVE}' does not exist.`);
      } else {
        const archiveDigest = sha256File(process.env.BUNDLE_ARCHIVE);
        if (archiveDigest !== manifest.bundle.sha256) {
          problems.push('bundle.sha256 does not match the checksum of the supplied release bundle.');
        }
      }
    }
  }

  const requiredRole = process.env.RELEASE_REQUIRED_APPROVAL_ROLE || 'release-manager';
  if (!Array.isArray(manifest.approvals) || manifest.approvals.length === 0) {
    problems.push('approvals must contain at least one recorded approval.');
  } else {
    let roleFound = false;
    for (const approval of manifest.approvals) {
      if (!approval || typeof approval !== 'object') {
        problems.push('each approval must be an object.');
        continue;
      }
      if (typeof approval.role !== 'string' || approval.role.trim().length === 0) {
        problems.push('each approval must record a role.');
      } else if (approval.role === requiredRole) {
        roleFound = true;
      }
      if (typeof approval.approver !== 'string' || approval.approver.trim().length === 0) {
        problems.push('each approval must record an approver.');
      }
      if (!isIsoTimestamp(approval.approvedAt)) {
        problems.push('each approval must record an ISO-8601 approvedAt timestamp.');
      } else if (Date.parse(approval.approvedAt) > Date.now()) {
        problems.push('an approval timestamp is in the future.');
      }
    }
    if (!roleFound) {
      problems.push(`approvals must include an approval for the required role '${requiredRole}'.`);
    }
  }

  const summary = manifest.exceptionSummary;
  if (!summary || typeof summary !== 'object') {
    problems.push('exceptionSummary must record the security and contract exceptions that were evaluated.');
  } else {
    const expectedCounts = {
      vulnerabilityExceptions: countExceptions(path.join('security', 'vulnerability-exceptions.json')),
      licenseExceptions: countExceptions(path.join('security', 'license-exceptions.json')),
      contractExceptions: countExceptions(path.join('security', 'contract-gate-exceptions.json')),
    };
    for (const [key, expected] of Object.entries(expectedCounts)) {
      const value = summary[key];
      if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
        problems.push(`exceptionSummary.${key} must be a non-negative integer.`);
        continue;
      }
      if (expected !== null && value !== expected) {
        problems.push(
          `exceptionSummary.${key} is ${value} but the repository registry currently holds ${expected} exception(s).`
        );
      }
    }
  }

  const signaturePath = process.env.RELEASE_MANIFEST_SIGNATURE || '';
  const publicKeyPath = process.env.RELEASE_MANIFEST_PUBLIC_KEY || '';
  const signatureRequired = process.env.REQUIRE_RELEASE_MANIFEST_SIGNATURE === 'true';

  if (signaturePath && publicKeyPath) {
    if (!fs.existsSync(signaturePath)) {
      problems.push(`RELEASE_MANIFEST_SIGNATURE '${signaturePath}' does not exist.`);
    } else if (!fs.existsSync(publicKeyPath)) {
      problems.push(`RELEASE_MANIFEST_PUBLIC_KEY '${publicKeyPath}' does not exist.`);
    } else {
      const verification = verifySignature(options.manifest, signaturePath, publicKeyPath);
      report.signature = verification;
      if (!verification.verified) {
        problems.push(`the release manifest signature could not be verified (${verification.failures.join('; ')}).`);
      }
    }
  } else if (signatureRequired) {
    problems.push(
      'a signed release manifest is required: set RELEASE_MANIFEST_SIGNATURE and RELEASE_MANIFEST_PUBLIC_KEY.'
    );
  } else {
    report.signature = { verified: false, method: '', failures: ['no signature was supplied'] };
  }

  report.problems = problems;
  report.ok = problems.length === 0;

  if (options.json) {
    process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  } else {
    for (const problem of problems) {
      process.stderr.write(`Release manifest error: ${problem}\n`);
    }
    process.stdout.write(
      report.ok
        ? `Release manifest is valid${report.signature.verified ? ` and the signature verified (${report.signature.method}).` : '.'}\n`
        : 'Release manifest validation failed.\n'
    );
  }

  return report.ok ? 0 : 1;
}

if (require.main === module) {
  process.exitCode = main();
}

module.exports = { parseArguments, verifySignature };
